"use client";

import { useState } from "react";

interface NewConnectorModalProps {
  onClose: () => void;
  onCreated: () => void;
}

const providerOptions = [
  {
    value: "gemini",
    label: "Google Gemini",
  },
  {
    value: "groq",
    label: "Groq",
  },
];

const modelOptions = {
  gemini: [
    {
      value: "gemini-2.5-flash",
      label: "Gemini 2.5 Flash",
    },
    {
      value: "gemini-2.5-pro",
      label: "Gemini 2.5 Pro",
    },
  ],

  groq: [
    {
      value: "openai/gpt-oss-120b",
      label: "GPT-OSS 120B",
    },
    {
      value: "openai/gpt-oss-20b",
      label: "GPT-OSS 20B",
    },
  ],
};

const inputOptions = [
  {
    value: "text",
    label: "Text",
  },
  {
    value: "number",
    label: "Number",
  },
  {
    value: "boolean",
    label: "Boolean",
  },
  {
    value: "image",
    label: "Image",
  },
  {
    value: "file",
    label: "File",
  },
  {
    value: "json",
    label: "JSON",
  },
];

const outputOptions = [
  {
    value: "json",
    label: "Structured JSON",
  },
  {
    value: "text",
    label: "Plain Text",
  },
];

function createSlug(name: string) {
  return name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export default function NewConnectorModal({
  onClose,
  onCreated,
}: NewConnectorModalProps) {

  const [name, setName] = useState("");
  const [description, setDescription] =
    useState("");

  const [provider, setProvider] =
    useState("gemini");

  const [model, setModel] =
    useState("gemini-2.5-flash");

  const [prompt, setPrompt] =
    useState("");

  const [inputType, setInputType] =
    useState("text");

  const [outputFormat, setOutputFormat] =
    useState("json");

  const [isActive, setIsActive] =
    useState(true);

  const [creating, setCreating] =
    useState(false);

  const [error, setError] =
    useState("");

  function handleProviderChange(
    value: string
  ) {
    setProvider(value);

    if (value === "gemini") {
      setModel("gemini-2.5-flash");
    } else {
      setModel("openai/gpt-oss-120b");
    }
  }

  async function handleSubmit(
    event: React.FormEvent<HTMLFormElement>
  ) {
    event.preventDefault();

    setError("");

    if (!name.trim()) {
      setError(
        "Connector name is required."
      );
      return;
    }

    if (!prompt.trim()) {
      setError(
        "Prompt instructions are required."
      );
      return;
    }

    setCreating(true);

    try {
      const slug = createSlug(name);

      const payload = {
        name: name.trim(),

        slug,

        description:
          description.trim(),

        provider,

        model,

        prompt: prompt.trim(),

        inputSchema: {
          input: {
            type: inputType,
            required: true,
          },
        },

        outputSchema:
          outputFormat === "json"
            ? {
                result: "string",
              }
            : {
                result: "text",
              },

        authType: "api_key",

        isActive,
      };

      console.log(
        "CREATING CONNECTOR:",
        payload
      );

      const response =
        await fetch(
          "/api/connectors",
          {
            method: "POST",

            headers: {
              "Content-Type":
                "application/json",
            },

            body: JSON.stringify(
              payload
            ),
          }
        );

      const data =
        await response.json();

      console.log(
        "CREATE RESPONSE:",
        data
      );

      if (!response.ok) {
        throw new Error(
          data?.error ||
            "Failed to create connector."
        );
      }

      onCreated();

      onClose();

    } catch (err) {

      console.error(
        "Failed to create connector:",
        err
      );

      setError(
        err instanceof Error
          ? err.message
          : "Something went wrong."
      );

    } finally {
      setCreating(false);
    }
  }

  const availableModels =
    modelOptions[
      provider as keyof typeof modelOptions
    ] ?? [];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-4 backdrop-blur-md">

      <div
        className="absolute inset-0"
        onClick={onClose}
      />

      <div className="relative z-10 max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-3xl border border-white/10 bg-[#0a0d15] shadow-2xl shadow-cyan-500/10">

        {/* Glow */}
        <div className="pointer-events-none absolute -left-24 -top-24 h-48 w-48 rounded-full bg-cyan-500/10 blur-3xl" />

        <div className="pointer-events-none absolute -bottom-24 -right-24 h-48 w-48 rounded-full bg-violet-500/10 blur-3xl" />

        {/* Header */}
        <div className="relative flex items-center justify-between border-b border-white/10 px-7 py-6">

          <div>

            <div className="mb-2 flex items-center gap-2">

              <span className="h-2 w-2 rounded-full bg-cyan-400 shadow-[0_0_12px_rgba(34,211,238,0.8)]" />

              <span className="text-xs font-medium uppercase tracking-[0.2em] text-cyan-400">
                AI Infrastructure
              </span>

            </div>

            <h2 className="text-xl font-semibold text-white">
              Create New Connector
            </h2>

            <p className="mt-1 text-sm text-slate-400">
              Configure a reusable AI-powered API endpoint.
            </p>

          </div>

          <button
            type="button"
            onClick={onClose}
            className="flex h-10 w-10 items-center justify-center rounded-xl border border-white/10 bg-white/[0.03] text-xl text-slate-400 transition hover:border-white/20 hover:bg-white/[0.06] hover:text-white"
          >
            ×
          </button>

        </div>

        {/* Form */}
        <form
          onSubmit={handleSubmit}
          className="relative space-y-6 p-7"
        >

          {/* Name + Description */}
          <div className="grid gap-5 md:grid-cols-2">

            <div>

              <label className="mb-2 block text-sm font-medium text-slate-300">
                Connector Name
              </label>

              <input
                value={name}
                onChange={(e) =>
                  setName(e.target.value)
                }
                placeholder="e.g. Article Writer"
                className="w-full rounded-xl border border-white/10 bg-white/[0.03] px-4 py-3 text-sm text-white outline-none transition placeholder:text-slate-600 focus:border-cyan-400/50 focus:bg-white/[0.05]"
              />

            </div>

            <div>

              <label className="mb-2 block text-sm font-medium text-slate-300">
                Description
              </label>

              <input
                value={description}
                onChange={(e) =>
                  setDescription(
                    e.target.value
                  )
                }
                placeholder="What does this API do?"
                className="w-full rounded-xl border border-white/10 bg-white/[0.03] px-4 py-3 text-sm text-white outline-none transition placeholder:text-slate-600 focus:border-cyan-400/50 focus:bg-white/[0.05]"
              />

            </div>

          </div>

          {/* Provider + Model */}
          <div className="grid gap-5 md:grid-cols-2">

            <div>

              <label className="mb-2 block text-sm font-medium text-slate-300">
                AI Provider
              </label>

              <select
                value={provider}
                onChange={(e) =>
                  handleProviderChange(
                    e.target.value
                  )
                }
                className="w-full rounded-xl border border-white/10 bg-[#0d111b] px-4 py-3 text-sm text-white outline-none focus:border-cyan-400/50"
              >

                {providerOptions.map(
                  (option) => (
                    <option
                      key={option.value}
                      value={option.value}
                    >
                      {option.label}
                    </option>
                  )
                )}

              </select>

            </div>

            <div>

              <label className="mb-2 block text-sm font-medium text-slate-300">
                Model
              </label>

              <select
                value={model}
                onChange={(e) =>
                  setModel(
                    e.target.value
                  )
                }
                className="w-full rounded-xl border border-white/10 bg-[#0d111b] px-4 py-3 text-sm text-white outline-none focus:border-cyan-400/50"
              >

                {availableModels.map(
                  (option) => (
                    <option
                      key={option.value}
                      value={option.value}
                    >
                      {option.label}
                    </option>
                  )
                )}

              </select>

            </div>

          </div>

          {/* Prompt */}
          <div>

            <label className="mb-2 block text-sm font-medium text-slate-300">
              System Prompt / Instructions
            </label>

            <textarea
              value={prompt}
              onChange={(e) =>
                setPrompt(
                  e.target.value
                )
              }
              rows={6}
              placeholder="Tell the AI exactly what this connector should do..."
              className="w-full resize-none rounded-xl border border-white/10 bg-white/[0.03] px-4 py-3 text-sm leading-6 text-white outline-none transition placeholder:text-slate-600 focus:border-cyan-400/50 focus:bg-white/[0.05]"
            />

            <p className="mt-2 text-xs text-slate-500">
              These instructions are combined with the user's runtime input when the API is called.
            </p>

          </div>

          {/* Input + Output */}
          <div className="grid gap-5 md:grid-cols-2">

            <div>

              <label className="mb-2 block text-sm font-medium text-slate-300">
                Input Type
              </label>

              <select
                value={inputType}
                onChange={(e) =>
                  setInputType(
                    e.target.value
                  )
                }
                className="w-full rounded-xl border border-white/10 bg-[#0d111b] px-4 py-3 text-sm text-white outline-none focus:border-cyan-400/50"
              >

                {inputOptions.map(
                  (option) => (
                    <option
                      key={option.value}
                      value={option.value}
                    >
                      {option.label}
                    </option>
                  )
                )}

              </select>

            </div>

            <div>

              <label className="mb-2 block text-sm font-medium text-slate-300">
                Output Format
              </label>

              <select
                value={outputFormat}
                onChange={(e) =>
                  setOutputFormat(
                    e.target.value
                  )
                }
                className="w-full rounded-xl border border-white/10 bg-[#0d111b] px-4 py-3 text-sm text-white outline-none focus:border-cyan-400/50"
              >

                {outputOptions.map(
                  (option) => (
                    <option
                      key={option.value}
                      value={option.value}
                    >
                      {option.label}
                    </option>
                  )
                )}

              </select>

            </div>

          </div>

          {/* Authentication */}
          <div className="rounded-2xl border border-white/10 bg-white/[0.02] p-5">

            <div className="flex items-center justify-between">

              <div>

                <p className="text-sm font-medium text-white">
                  API Authentication
                </p>

                <p className="mt-1 text-xs text-slate-500">
                  Generated endpoints will require API-key authentication.
                </p>

              </div>

              <div className="rounded-lg border border-cyan-400/20 bg-cyan-400/5 px-3 py-2 text-xs font-medium text-cyan-300">
                API Key
              </div>

            </div>

          </div>

          {/* Active */}
          <div className="flex items-center justify-between rounded-2xl border border-white/10 bg-white/[0.02] p-5">

            <div>

              <p className="text-sm font-medium text-white">
                Connector Status
              </p>

              <p className="mt-1 text-xs text-slate-500">
                {isActive
                  ? "This connector is available for API requests."
                  : "This connector is disabled and cannot receive requests."}
              </p>

            </div>

            <button
              type="button"
              onClick={() =>
                setIsActive(
                  (current) =>
                    !current
                )
              }
              className={`relative h-7 w-12 rounded-full transition ${
                isActive
                  ? "bg-cyan-400/80"
                  : "bg-slate-700"
              }`}
            >

              <span
                className={`absolute top-1 h-5 w-5 rounded-full bg-white shadow transition ${
                  isActive
                    ? "left-6"
                    : "left-1"
                }`}
              />

            </button>

          </div>

          {/* Error */}
          {error && (
            <div className="rounded-xl border border-red-400/20 bg-red-400/5 px-4 py-3 text-sm text-red-300">
              {error}
            </div>
          )}

          {/* Footer */}
          <div className="flex items-center justify-end gap-3 border-t border-white/10 pt-6">

            <button
              type="button"
              onClick={onClose}
              disabled={creating}
              className="rounded-xl border border-white/10 px-5 py-3 text-sm font-medium text-slate-300 transition hover:bg-white/[0.05] hover:text-white"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={creating}
              className="rounded-xl bg-cyan-400 px-6 py-3 text-sm font-semibold text-slate-950 transition hover:bg-cyan-300 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {creating
                ? "Creating..."
                : "Create Connector"}
            </button>

          </div>

        </form>

      </div>

    </div>
  );
}